class Gs1ProductPage{static async render(params){function formatDate(date,locale='en-US'){if(!date)return'';const[year,month,day]=date.split('-').map(Number);return new Date(year,month-1,day).toLocaleDateString(locale,{weekday:'long',year:'numeric',month:'long',day:'numeric'});}
const $page=$('#gs1-product-page');try{if(!params)
throw new Error("Empty parameters");if(params.error)
throw new Error(params.error);document.title=params.gtin;$('.gs1-gtin',$page).text(params.gtin);if(params.lot)
$('.gs1-lot',$page).text(params.lot);if(params.serial)
$('.gs1-serial',$page).text(params.serial);if(params.productionDate)
$('.gs1-production-date',$page).text(formatDate(params.productionDate));if(params.expiryDate)
$('.gs1-expiry-date',$page).text(formatDate(params.expiryDate));if(params.softwareVersion)
$('.gs1-software-version',$page).text(params.softwareVersion);const app=simplicite.session({url:params.serverURL,debug:false});const gtinObj=app.getBusinessObject('Gs1Gtin');const gtinRows=await gtinObj.search({gs1GtinIdentifier:params.gtin},{inlineImages:['gs1GtinPicture']});if(gtinRows.length==1){const gtinRow=gtinRows[0];$('.gs1-gtin-picture',$page).attr('src',gtinObj.getFieldDataURL('gs1GtinPicture',gtinRow)).show();$('.gs1-gtin-label',$page).text(gtinRow.gs1GtinLabel);$('.gs1-gtin-description',$page).html(gtinRow.gs1GtinDescription);const udiObj=app.getBusinessObject('Gs1Udi');const udiRows=await udiObj.search({gs1UdiGtinId__gs1GtinIdentifier:params.gtin,gs1UdiLot:params.lot||'',gs1UdiSerial:params.serial||'',gs1UdiProductionDate:params.productionDate||'',gs1UdiExpiryDate:params.expiryDate||'',gs1UdiSoftwareVersion:params.softwareVersion||'',},{inlineImages:['gs1UdiGs1128Image']});if(udiRows.length==1){const udiRow=udiRows[0];$('.gs1-udi-description',$page).html(udiRow.gs1UdiDescription);$('.gs1-udi-picture',$page).attr('src',udiObj.getFieldDataURL('gs1UdiGs1128Image',udiRow)).show();}else
throw new Error("UDI not found");}else
throw new Error('GTIN not found');}catch(err){$('.error',$page).text(err).show();}}}